def build_meta_prompt(context):
    evidence = context['evidence_ids']
    round = context.get('round', 0)
    ranked = []
    failed = []
    for eid in evidence:
        if 'fixed-a/00' in eid:
            failed.append(eid)
        elif eid not in ranked:
            ranked.append(eid)
    for eid in failed:
        if eid not in ranked:
            ranked.append(eid)
    if not ranked:
        ranked = evidence[:4]
    ranked = ranked[:4]
    if failed:
        return str({'mode': 'repair', 'evidence': ranked, 'guidance': 'Repair the search around the feasible fixed-b runs and the best fixed-a run, avoiding reliance on the failed provider case.'})
    if round % 3 == 2:
        return str({'mode': 'rethink', 'evidence': ranked, 'guidance': 'Rethink the placement and reclamation balance using only feasible evidence, then preserve the strongest operator.'})
    return str({'mode': 'revise', 'evidence': ranked, 'guidance': 'Revise the next search by prioritizing the best feasible evidence and mutating the strongest archived parent.'})
